/*
 * prog47_circular_queue.c
 *
 * A tiny circular queue (capacity 5) driven by command‑line arguments.
 *
 * Supported commands (each argument is a separate command):
 *
 *   E<number>   – enqueue the signed decimal number <number>.
 *                 Prints  "ENQ %ld" on success,
 *                 "FULL" if the queue is already full,
 *                 "ERR"  if the number cannot be parsed.
 *
 *   D           – dequeue the element at the front of the queue.
 *                 Prints  "DEQ %ld" on success,
 *                 "EMPTY" if the queue is empty.
 *
 *   F           – show the element at the front without removing it.
 *                 Prints  "FRONT %ld" on success,
 *                 "EMPTY" if the queue is empty.
 *
 *   (no arguments) – prints "NOOP".
 *
 * Any other argument results in "ERR".
 *
 * The program’s output matches exactly the strings found in the original
 * binary (ENQ, DEQ, FRONT, EMPTY, FULL, NOOP, ERR).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 5

static long items[CAPACITY];
static int  head  = 0;   /* index of the first element */
static int  count = 0;   /* number of elements currently stored */

int main(int argc, char **argv)
{
    /* No command‑line arguments → the original binary prints “NOOP”. */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];

        /* ENQ command – starts with 'E' followed by a decimal number. */
        if (arg[0] == 'E' && arg[1] != '\0') {
            char *endptr;
            long value = strtol(arg + 1, &endptr, 10);

            if (endptr == arg + 1) {          /* nothing was parsed */
                puts("ERR");
                continue;
            }

            if (count == CAPACITY) {          /* queue already full */
                puts("FULL");
                continue;
            }

            items[(head + count) % CAPACITY] = value;
            ++count;
            printf("ENQ %ld\n", value);
            continue;
        }

        /* DEQ command – exactly the single character "D". */
        if (strcmp(arg, "D") == 0) {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }

            long value = items[head];
            head = (head + 1) % CAPACITY;
            --count;
            printf("DEQ %ld\n", value);
            continue;
        }

        /* FRONT command – exactly the single character "F". */
        if (strcmp(arg, "F") == 0) {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }

            long value = items[head];
            printf("FRONT %ld\n", value);
            continue;
        }

        /* Anything else is an error. */
        puts("ERR");
    }

    return 0;
}
